using System;
using System.Collections.Generic;
using UnityEngine;

// Generated by SpriteAlphaMaskBuilder. Source textures need not be CPU-readable.
public sealed class SpriteAlphaMaskDatabase : ScriptableObject
{
    [Serializable]
    public sealed class Entry
    {
        public Sprite sprite;
        public int width, height;
        public byte[] alpha;
        [NonSerialized] private bool bottomComputed;
        [NonSerialized] private float bottom;

        public float OpaqueBottom()
        {
            if (bottomComputed) return bottom;
            bottomComputed = true;
            for (int y = 0; y < height; y++)
                for (int x = 0; x < width; x++)
                    if (alpha[y * width + x] >= 26)
                        return bottom = (float)y / height;
            return bottom = 0f;
        }

        public float Sample(Vector2 uv, bool point)
        {
            if (point)
                return At(Mathf.FloorToInt(uv.x * width), Mathf.FloorToInt(uv.y * height));
            float x = uv.x * width - .5f, y = uv.y * height - .5f;
            int ix = Mathf.FloorToInt(x), iy = Mathf.FloorToInt(y);
            return Mathf.Lerp(Mathf.Lerp(At(ix, iy), At(ix + 1, iy), x - ix),
                Mathf.Lerp(At(ix, iy + 1), At(ix + 1, iy + 1), x - ix), y - iy);
        }

        private float At(int x, int y) => alpha[Mathf.Clamp(y, 0, height - 1) * width +
            Mathf.Clamp(x, 0, width - 1)] / 255f;
    }

    public const string ResourceName = "SpriteAlphaMasks";
    [SerializeField, HideInInspector] private string sourceFingerprint;
    [SerializeField, HideInInspector] private List<Entry> entries = new List<Entry>();
    private Dictionary<Sprite, Entry> index;
    private static SpriteAlphaMaskDatabase loaded;
    public string SourceFingerprint => sourceFingerprint;
    public int Count => entries.Count;

    public static bool TryGetOpaqueBottom(Sprite sprite, out float bottom)
    {
        bottom = 0f;
        if (!TrySample(sprite, Vector2.zero, out _)) return false;
        bottom = loaded.index[sprite].OpaqueBottom();
        return true;
    }

    public static bool TrySample(Sprite sprite, Vector2 uv, out float alpha)
    {
        if (loaded == null) loaded = Resources.Load<SpriteAlphaMaskDatabase>(ResourceName);
        alpha = 0f;
        return loaded != null && loaded.Sample(sprite, uv, out alpha);
    }

    private bool Sample(Sprite sprite, Vector2 uv, out float alpha)
    {
        if (index == null)
        {
            index = new Dictionary<Sprite, Entry>();
            foreach (var entry in entries)
                if (entry.sprite != null && entry.width > 0 && entry.height > 0 &&
                    entry.alpha != null && entry.alpha.Length == entry.width * entry.height)
                    index[entry.sprite] = entry;
        }
        alpha = 0f;
        if (sprite == null || !index.TryGetValue(sprite, out var mask)) return false;
        alpha = mask.Sample(uv, sprite.texture.filterMode == FilterMode.Point);
        return true;
    }

    private void OnEnable() { index = null; }
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    public static void ResetCache() { loaded = null; }

#if UNITY_EDITOR
    public void ReplaceGeneratedData(string fingerprint, List<Entry> masks)
    {
        sourceFingerprint = fingerprint;
        entries = masks;
        index = null;
        ResetCache();
    }
#endif
}
